type Shape = { kind: "circle"; radius: number } | { kind: "square"; side: number };

function collide(a: Shape, b: Shape): string {
  switch (a.kind) {
    case "circle": switch (b.kind) {
      case "square": return `circle ${a.radius} vs square ${b.side}`;
      case "circle": return "two circles";
    }
    case "square": switch (b.kind) {
      case "circle": return collide(b, a);     // canonicalise symmetric pairs
      case "square": return "two squares";
    }
  }
}

